insert into t_lh_schedule_result ( id, batch_no, order_no, lh_machine_code， left_right_mold, sap_code， embryo_code, spec_desc， stock_area， lh_time， change_mold_time, daily_plan_qty， schedule_date， production_status， class1_plan_qty， class1_start_time, class1_end_time, class1_analysis， class1_analysis_input， class1_analysis_code， class2_plan_qty， class2_start_time, class2_end_time, class2_analysis， class2_analysis_input， class2_analysis_code， class3_plan_qty， class3_start_time, class3_end_time, class3_analysis， class3_analysis_input， class3_analysis_code， is_release， create_by, update_by, update_time, remark ) select SEQ_LH_SCHEDULE.NEXTVAL AS ID, x.* from (
select #{schedule.batchNo,jdbcType=VARCHAR}, #{schedule.orderNo,jdbcType=VARCHAR}, #{schedule.lhMachineCode,jdbcType=VARCHAR}, #{schedule.leftRightMold,jdbcType=VARCHAR}, #{schedule.sapCode,jdbcType=VARCHAR}, #{schedule.embryoCode,jdbcType=VARCHAR}, #{schedule.specDesc,jdbcType=VARCHAR}, #{schedule.stockArea,jdbcType=VARCHAR}, #{schedule.lhTime,jdbcType=DOUBLE}, #{schedule.changeMoldTime,jdbcType=DATE}, #{schedule.dailyPlanQty,jdbcType=INTEGER}, #{schedule.scheduleDate}, #{schedule.productionStatus,jdbcType=VARCHAR}, #{schedule.class1PlanQty,jdbcType=INTEGER}, #{schedule.class1StartTime,jdbcType=DATE}, #{schedule.class1EndTime,jdbcType=DATE}, #{schedule.class1Analysis,jdbcType=VARCHAR}, #{schedule.class1AnalysisInput,jdbcType=VARCHAR}, #{schedule.class1AnalysisCode,jdbcType=VARCHAR}, #{schedule.class2PlanQty,jdbcType=INTEGER}, #{schedule.class2StartTime,jdbcType=DATE}, #{schedule.class2EndTime,jdbcType=DATE}, #{schedule.class2Analysis,jdbcType=VARCHAR}, #{schedule.class2AnalysisInput,jdbcType=VARCHAR}, #{schedule.class2AnalysisCode,jdbcType=VARCHAR}, #{schedule.class3PlanQty,jdbcType=INTEGER}, #{schedule.class3StartTime,jdbcType=DATE}, #{schedule.class3EndTime,jdbcType=DATE}, #{schedule.class3Analysis,jdbcType=VARCHAR}, #{schedule.class3AnalysisInput,jdbcType=VARCHAR}, #{schedule.class3AnalysisCode,jdbcType=VARCHAR}, #{schedule.isRelease,jdbcType=VARCHAR}, #{schedule.createBy,jdbcType=VARCHAR}, #{schedule.updateBy,jdbcType=VARCHAR}, #{schedule.updateTime,jdbcType=DATE}, #{schedule.remark,jdbcType=VARCHAR} from dual
) x

mapper.update:
update T_LH_SCHEDULE_RESULT
lh_machine_code = #{lhMachineCode}, lh_machine_name = #{lhMachineName}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}, is_release = #{isRelease},
